const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const d = $json;
const P = d.pipeline || {};
const pct = (a, b) => (b ? Math.round((a / b) * 100) : 0);
const scoreClass = (s) => (s >= 85 ? 'hot' : s >= 70 ? 'good' : s >= 50 ? 'mid' : 'low');
const LABEL = { new: 'Nouvelle', shortlisted: 'Sélectionnée', applied: 'Postulé', interview: 'Entretien', offer: 'Offre', rejected: 'Refus', ignored: 'Ignorée', ghosted: 'Sans réponse' };

// --- Graphique d'activité (SVG) ---
const act = d.activity || [];
const maxAct = Math.max(1, ...act.map((a) => Math.max(a.collected, a.applied)));
const W = 640, H = 180, bw = W / Math.max(1, act.length);
const bars = act.map((a, i) => {
  const h1 = (a.collected / maxAct) * (H - 30), h2 = (a.applied / maxAct) * (H - 30);
  return `<g><title>${a.label} : ${a.collected} offres, ${a.applied} candidatures</title>
    <rect x="${i * bw + 4}" y="${H - 20 - h1}" width="${bw / 2 - 4}" height="${h1}" rx="3" class="b1"/>
    <rect x="${i * bw + bw / 2}" y="${H - 20 - h2}" width="${bw / 2 - 4}" height="${h2}" rx="3" class="b2"/>
    ${i % 2 === 0 ? `<text x="${i * bw + bw / 2}" y="${H - 4}" text-anchor="middle">${a.label}</text>` : ''}</g>`;
}).join('');

// --- Funnel ---
const applied = d.applications || 0;
const funnel = [
  ['Offres analysées', d.total_jobs - d.pending],
  [`Pépites (≥ ${d.threshold})`, d.top_matches],
  ['Candidatures', applied],
  ['Entretiens', (P.interview || 0) + (P.offer || 0)],
  ['Offres reçues', P.offer || 0],
];
const fMax = Math.max(1, funnel[0][1]);
const funnelHtml = funnel.map(([l, v]) => `<div class="frow"><span>${l}</span><div class="fbar"><i style="width:${Math.max(2, pct(v, fMax))}%"></i></div><b>${v}</b></div>`).join('');

// --- Histogramme des scores ---
const hist = Array.from({ length: 10 }, (_, i) => (d.score_histogram || []).find((h) => h.bucket === i * 10)?.n || 0);
const hMax = Math.max(1, ...hist);
const histHtml = hist.map((n, i) => `<div class="hcol" title="${i * 10}-${i * 10 + 9} : ${n} offres"><i class="${scoreClass(i * 10 + 5)}" style="height:${pct(n, hMax)}%"></i><span>${i * 10}</span></div>`).join('');

// --- Kanban ---
const cols = ['applied', 'interview', 'offer', 'rejected', 'ghosted'];
const kanban = cols.map((c) => {
  const items = (d.applications_list || []).filter((a) => a.status === c);
  return `<div class="col"><h4>${LABEL[c]} <small>${items.length}</small></h4>${items.map((a) =>
    `<div class="card"><b>${esc(a.title)}</b><span>${esc(a.company || '—')}</span><em>Postulé le ${a.applied} · J+${a.days}${a.followup_count ? ' · ' + a.followup_count + ' relance(s)' : ''}</em></div>`).join('') || '<p class="empty">—</p>'}</div>`;
}).join('');

const topRows = (d.top_jobs || []).map((j) => `<tr><td><span class="score ${scoreClass(j.score)}">${j.score}</span></td>
  <td><a href="${esc(j.url || '#')}" target="_blank" rel="noopener">${esc(j.title)}</a><small>#${j.id} · ${j.day}</small></td>
  <td>${esc(j.company || '—')}</td><td>${esc(j.location || '—')}</td><td>${LABEL[j.status]}</td></tr>`).join('');

const sk = d.missing_skills || [];
const skMax = Math.max(1, ...sk.map((s) => s.occurrences));
const skills = sk.map((s) => `<div class="frow"><span>${esc(s.skill)}</span><div class="fbar alt"><i style="width:${pct(s.occurrences, skMax)}%"></i></div><b>${s.occurrences}</b></div>`).join('') || '<p class="empty">Pas encore assez de données.</p>';

const sources = (d.sources || []).map((s) => `<tr><td><span class="dot ${!s.active ? 'off' : s.error ? 'warn' : 'on'}"></span>${esc(s.kind)}</td><td>${esc(s.name)}</td><td>${s.last_count ?? '—'}</td><td>${s.last_run || 'jamais'}</td><td class="err">${esc((s.error || '').slice(0, 60))}</td></tr>`).join('');
const errors = (d.errors || []).map((e) => `<li><b>${e.at}</b> · ${esc(e.workflow_name)} › ${esc(e.node_name)} : ${esc((e.message || '').slice(0, 140))}</li>`).join('') || '<li class="empty">Aucune erreur récente 🎉</li>';

const kpis = [
  ['Offres collectées', d.total_jobs, `+${d.jobs_24h} en 24 h`],
  ['Score moyen', d.avg_score ?? '—', `${d.pending} en attente d'analyse`],
  ['Pépites', d.top_matches, `score ≥ ${d.threshold}`],
  ['Candidatures', applied, `${d.letters} lettres générées`],
  ['Taux de réponse', pct(d.answered, applied) + '%', `${d.answered} réponses`],
  ['Entretiens', (P.interview || 0) + (P.offer || 0), `${P.offer || 0} offre(s) reçue(s)`],
].map(([l, v, s]) => `<div class="kpi"><span>${l}</span><b>${v}</b><small>${s}</small></div>`).join('');

const html = `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Job Hunter IA · Dashboard</title>
<style>
:root{--bg:#f6f7fb;--panel:#fff;--text:#1d2433;--muted:#6b7385;--line:#e6e8ef;--accent:#4f46e5;--accent2:#14b8a6;--hot:#ef4444;--good:#22c55e;--mid:#f59e0b;--low:#94a3b8}
@media (prefers-color-scheme:dark){:root{--bg:#0f1220;--panel:#171b2e;--text:#e8eaf2;--muted:#9aa3b8;--line:#272c45;--accent:#818cf8;--accent2:#2dd4bf}}
*{box-sizing:border-box}body{margin:0;font:14px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--text)}
header{padding:28px 32px 8px;display:flex;justify-content:space-between;align-items:end;flex-wrap:wrap;gap:8px}
h1{margin:0;font-size:24px}h1 span{color:var(--accent)}header p{margin:0;color:var(--muted)}
main{padding:16px 32px 40px;display:grid;gap:16px;grid-template-columns:repeat(12,1fr)}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px}
.panel h3{margin:0 0 12px;font-size:15px}.s12{grid-column:span 12}.s8{grid-column:span 8}.s6{grid-column:span 6}.s4{grid-column:span 4}
@media(max-width:1000px){.s8,.s6,.s4{grid-column:span 12}main,header{padding-left:16px;padding-right:16px}}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}
.kpi{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:14px 16px;display:flex;flex-direction:column}
.kpi span{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.04em}.kpi b{font-size:28px}.kpi small{color:var(--muted)}
svg{width:100%;height:auto}svg text{fill:var(--muted);font-size:10px}.b1{fill:var(--accent)}.b2{fill:var(--accent2)}
.legend{display:flex;gap:14px;color:var(--muted);font-size:12px}.legend i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:5px}
.frow{display:grid;grid-template-columns:150px 1fr 40px;gap:10px;align-items:center;margin:7px 0}.frow span{color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fbar{background:var(--line);border-radius:6px;height:12px;overflow:hidden}.fbar i{display:block;height:100%;background:var(--accent);border-radius:6px}.fbar.alt i{background:var(--mid)}
.hist{display:flex;gap:6px;align-items:end;height:150px}.hcol{flex:1;display:flex;flex-direction:column;justify-content:end;height:100%;text-align:center}
.hcol i{display:block;border-radius:5px 5px 0 0;min-height:2px}.hcol span{color:var(--muted);font-size:11px}
.hot{background:var(--hot)}.good{background:var(--good)}.mid{background:var(--mid)}.low{background:var(--low)}
table{width:100%;border-collapse:collapse}td,th{padding:9px 8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{color:var(--muted);font-weight:500;font-size:12px}
td small{display:block;color:var(--muted)}a{color:var(--text);text-decoration:none;font-weight:600}a:hover{color:var(--accent)}
.score{display:inline-block;min-width:36px;text-align:center;padding:3px 6px;border-radius:8px;color:#fff;font-weight:700}
.kanban{display:grid;grid-template-columns:repeat(5,minmax(160px,1fr));gap:12px;overflow-x:auto}.col{background:var(--bg);border-radius:12px;padding:10px}
.col h4{margin:2px 4px 10px;font-size:13px}.col h4 small{color:var(--muted);font-weight:400}
.card{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:10px;margin-bottom:8px;display:flex;flex-direction:column;gap:2px}
.card span,.card em{color:var(--muted);font-size:12px;font-style:normal}.empty{color:var(--muted)}
.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:8px}.dot.on{background:var(--good)}.dot.warn{background:var(--mid)}.dot.off{background:var(--low)}
.err{color:var(--hot);font-size:12px}ul{margin:0;padding-left:18px}li{margin:6px 0}footer{color:var(--muted);text-align:center;padding:0 0 30px}
</style></head><body>
<header><div><h1>🎯 Job Hunter <span>IA</span></h1><p>Tableau de bord de ${esc(d.full_name || 'ta recherche')}</p></div>
<p>Mis à jour le ${new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' })}</p></header>
<main>
<section class="s12 kpis">${kpis}</section>
<section class="panel s8"><h3>Activité des 14 derniers jours</h3><div class="legend"><span><i class="b1" style="background:var(--accent)"></i>Offres collectées</span><span><i style="background:var(--accent2)"></i>Candidatures</span></div><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Activité">${bars}</svg></section>
<section class="panel s4"><h3>Entonnoir de recrutement</h3>${funnelHtml}</section>
<section class="panel s12"><h3>Pipeline des candidatures</h3><div class="kanban">${kanban}</div></section>
<section class="panel s8"><h3>Meilleures offres à traiter</h3><table><thead><tr><th>Score</th><th>Poste</th><th>Entreprise</th><th>Lieu</th><th>Statut</th></tr></thead><tbody>${topRows || '<tr><td colspan="5" class="empty">Aucune offre analysée pour l’instant.</td></tr>'}</tbody></table></section>
<section class="panel s4"><h3>Distribution des scores</h3><div class="hist">${histHtml}</div><h3 style="margin-top:22px">Compétences à renforcer</h3>${skills}</section>
<section class="panel s8"><h3>Santé des sources</h3><table><thead><tr><th>Type</th><th>Source</th><th>Offres</th><th>Dernière collecte</th><th></th></tr></thead><tbody>${sources}</tbody></table></section>
<section class="panel s4"><h3>Erreurs récentes</h3><ul>${errors}</ul></section>
</main><footer>Propulsé par n8n · PostgreSQL · IA</footer></body></html>`;

return [{ json: { html } }];
